<?php require 'header.php';require_login();$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT * FROM orders WHERE id=? AND user_id=?');$s->execute([$id,user()['id']]);$o=$s->fetch();if(!$o){echo '<div class="container empty">ไม่พบคำสั่งซื้อ</div>';require 'footer.php';exit;}$s=$pdo->prepare('SELECT * FROM order_items WHERE order_id=?');$s->execute([$id]);$items=$s->fetchAll();?><div class="container"><h1>คำสั่งซื้อ #<?=$o['id']?></h1><p>สถานะ: <?=h($o['status'])?></p><p>ผู้รับ: <?=h($o['shipping_name'])?> · <?=h($o['shipping_phone'])?></p><p>ที่อยู่: <?=nl2br(h($o['shipping_address']))?></p><div class="table-wrap"><table><tr><th>สินค้า</th><th>ราคา</th><th>จำนวน</th><th>รวม</th></tr><?php foreach($items as $i):?><tr><td><?=h($i['product_name'])?></td><td>฿<?=money($i['price'])?></td><td><?=$i['quantity']?></td><td>฿<?=money($i['price']*$i['quantity'])?></td></tr><?php endforeach;?></table></div><h2 class="price">ยอดรวม ฿<?=money($o['total'])?></h2></div><?php require 'footer.php';?>
